def _line_indices(grid, color):
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if sum(v == color for v in grid[r]) >= 0.65 * w]
    cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.65 * h]
    return rows, cols


def _spread(indices):
    if len(indices) < 2:
        return None
    gaps = [b - a for a, b in zip(indices, indices[1:])]
    mean = sum(gaps) / len(gaps)
    variance = sum((gap - mean) ** 2 for gap in gaps) / len(gaps)
    return mean, variance


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)

    # The repeated scaffold color forms evenly spaced, nearly full rows and columns.
    best = None
    for color in counts:
        rows, cols = _line_indices(grid, color)
        row_spread, col_spread = _spread(rows), _spread(cols)
        if row_spread is None or col_spread is None:
            continue
        score = (row_spread[1] + col_spread[1], -len(rows) - len(cols))
        if best is None or score < best[0]:
            best = (score, color, rows, cols)
    if best is None:
        return [row[:] for row in grid]

    _, scaffold, rows, cols = best
    fill_counts = Counter(value for row in grid for value in row if value != scaffold)
    fill = fill_counts.most_common(1)[0][0]

    # Each output cell is the rectangle bounded by consecutive scaffold lines.
    # A unanimous non-scaffold corner marker is retained; mixed corners decode
    # to the repeated interior/fill color.
    result = []
    for r0, r1 in zip(rows, rows[1:]):
        out_row = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            if corners[0] != scaffold and all(value == corners[0] for value in corners):
                out_row.append(corners[0])
            else:
                out_row.append(fill)
        result.append(out_row)

    # Discard blank outer rectangles left by the framing lines.
    while result and all(value == fill for value in result[0]):
        result.pop(0)
    while result and all(value == fill for value in result[-1]):
        result.pop()
    if result:
        while all(row[0] == fill for row in result):
            for row in result:
                row.pop(0)
        while all(row[-1] == fill for row in result):
            for row in result:
                row.pop()
    return result


